import{enemyHint}from'./path-combat.js';import{TrailWorld}from'./trail-world.js';import{mechanismMarkup}from'./world-mechanisms.js';import{TrailNavigator}from'./trail-nav.js';import{TRAILS,collectCoin,equipTrail,upgradeTraversalSave,travelState}from'./traversal.js';import{AREAS,validSave as validLegacy}from'./core.js';import{ACTIVITIES,TASK_TYPES,STORE,LEGACY_STORE,activity,freshJourney,freshSave,required,progress,maximum,unlocked,ready,guardianReady,freshExpedition,expedition,currentType,chooseBranch,milestone,finishExpedition,winGuardian,restart,migrate,validSave,encode,chestPending,finishRun,runChapter}from'./expedition.js';import{activeNode,approachPoint,chapterPath,CHAPTERS,CHAPTER_LENGTH}from'./trail-layout.js';import{makeTask,actTask,taskFraction,taskHint}from'./trail-tasks.js';import{evolutionAudio}from'./evolution-audio.js';import{dayNumber,poolSize,recordAnswer,reviewPriority,itemIds,growthNeed,points as growthPoints,masteredCount,growthProgress,upgradeMastery,dueCount,isDue,wordex}from'./mastery.js';import{explainMistake}from'./mistakes.js';import{dailyState,questProgress,markPlayed,streakInfo,welcomeLine}from'./daily.js';import{useCosmetic}from'./cosmetics.js';import{campMarkup,onboardingMarkup,wordexMarkup,shopMarkup,correctionMarkup,runSummaryMarkup,growthBar}from'./camp-ui.js';import{Voice}from'./voice.js';import{floatText,burst,flyCoins,bump,flash,haptic,HAPTICS}from'./game-feel.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let save=freshSave(),units=[],world,nav,screen='home',modal=false,locked=false,task=null,resultCard=false,lastSnapshot=0,toastTimer,nearId='',autoOpenAfter=0,audioContext,evoState,evoStop,speechSupported='speechSynthesis'in window,feedbackText='',pendingCompletion=null;
const deviceChecks={};const gameAudio=new GameAudio(),voice=new Voice();let onboarding=false,onboardGrade=5,onboardName=null,correction=null,pendingSummary=null,shopTab='trail';let graphics=graphicsSettings(null);try{graphics=graphicsSettings(JSON.parse(localStorage.getItem(GRAPHICS_KEY)||'null'));}catch{}
const partner=()=>partnerInfo(save.partner);
const unit=()=>units.find(u=>u.id===save.selected)||units[0],journey=()=>{const j=save.journeys[save.selected]??=freshJourney();if(j.mastery===undefined)upgradeMastery(j);j.pool??=poolSize(unit());return j;},state=()=>expedition(journey(),save.selected,save.area);
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('toast-shown');document.body.classList.add('hud-notice');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('#toast').classList.remove('toast-shown');document.body.classList.remove('hud-notice');},3600);}
function snapshot(){if(nav&&nav.state===state()){state().position={...nav.player};state().heading=nav.heading;}}
function persist(){snapshot();try{localStorage.setItem(STORE,encode(save));$('#save-indicator').textContent='Checkpoint saved on this device';return true;}catch{$('#save-indicator').textContent='Not saved · export a backup';toast('This browser could not save. Export a backup from the journey journal.');return false;}}
function soundUpdate(){gameAudio.setMuted(save.muted);gameAudio.setMusicEnabled(save.music!==false);if(save.muted)gameAudio.silence();if(world){world.partner=partner().id;world.elementColor=partner().color;world.trailColor=save.wallet?.equipped==='air'?partner().color:TRAILS.find(t=>t.id===save.wallet?.equipped)?.color||partner().color;}$('#sound-button').style.opacity=save.muted?'.5':'1';$('#sound-button').setAttribute('aria-label',save.muted?'Enable sound':'Mute sound');}
function cue(kind='place'){if(save.muted)return;try{audioContext??=voice.context||new(window.AudioContext||window.webkitAudioContext)();gameAudio.attach(audioContext);if(!voice.context)voice.attach(audioContext);audioContext.resume()?.catch?.(()=>{});gameAudio.play(kind);}catch{}}
function tone(ok=true){cue(ok?'place':'wrong');}
function showModal(title,html){world.measurementPhase=null;modal=true;world.paused=true;world.setInput(0,0);$('#modal-layer').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2><button class="close" data-do="close-modal" aria-label="Close">×</button></div>${html}</section></div>`;$('.modal .close')?.focus();}
function closeModal(){modal=false;$('#modal-layer').innerHTML='';if(world)world.paused=false;}
function growthState(){const j=journey();return{next:Math.min(10,j.level+1),points:growthPoints(j),mastered:masteredCount(j),need:growthNeed(j),progress:j.level>=10?1:growthProgress(j)};}
// The run is the current chapter until its reward chest is opened.
function currentRun(){const e=state(),chapter=chestPending(e)?runChapter(e):Math.min(4,Math.floor(e.index/4));if(!e.run||e.run.chapter!==chapter||e.run.expedition!==e.id)e.run={expedition:e.id,chapter,correct:0,perfect:0,tasks:0,growth:0,learned:[],review:[],rivals:0};return e.run;}
const taskPriority=()=>reviewPriority(journey());
function quest(id,amount=1){const done=questProgress(save,id,amount);for(const q of done){toast(`Quest complete · ${q.label} · +${q.reward} coins`);cue('quest');buzz(HAPTICS.reward);const w=typeof innerWidth==='number'?innerWidth:400;rewardCoins(q.reward,{x:w/2,y:120});}return done;}
let coinsInFlight=0,lastTap=null,lastDamage=0;
const coinText=()=>Math.max(0,(save.wallet?.balance||0)-coinsInFlight);
function showCoins(){const c=$('#coin-count');if(c)c.textContent=coinText();}
function buzz(pattern){return haptic(pattern,{enabled:save.haptics!==false});}
// Coins fly from where they were earned to the counter, which ticks up as each arrives.
function rewardCoins(value,from){if(!value)return;const target=$('#coin-count');if(!target||!from||document.hidden){showCoins();return;}coinsInFlight+=value;showCoins();const n=Math.min(value,12);let left=value;flyCoins(from,target,n,i=>{const add=i===n-1?left:Math.min(left,Math.max(1,Math.floor(value/n)));left-=add;coinsInFlight=Math.max(0,coinsInFlight-add);showCoins();bump(target);cue('coinTick');});}
function feelDamage(r){lastDamage=Date.now();const final=r.hp<=0,p=world?.screenPoint?.({x:r.x,y:1.35,z:r.z});if(p)floatText(p.x,p.y,String(Math.ceil(100/Math.max(1,r.maxHp))),final?'crit':'damage');world?.juice?.hitstop(final?85:65);world?.juice?.shake(final?.42:.26);buzz(final?HAPTICS.crit:HAPTICS.hit);}
function feelImpact(p,hit){if(hit&&Date.now()-lastDamage<50)return;const s=world?.screenPoint?.({x:p.x,y:(p.y||.6)+.5,z:p.z});if(hit){if(s)floatText(s.x,s.y,'Crack!','crack');world?.juice?.hitstop(60);world?.juice?.shake(.22);buzz(HAPTICS.hit);}else{if(s)floatText(s.x,s.y,'Blocked','blocked');world?.juice?.shake(.08);}}
function feelHurt(){world?.juice?.hitstop(90);world?.juice?.shake(.5);flash('hurt');buzz(HAPTICS.hurt);}
function configureTravel(){nav.partner=partner().id;nav.enableTraversal(save.mode,{heading:()=>world?.controlHeading??nav.heading,face:heading=>{if(world){world.controlHeading=heading;if(world.locomotion)world.locomotion.heading=heading;}},combatSave:()=>persist(),trialSave:()=>persist(),trialReward:s=>{cue('break');let gained=0;for(let i=0;i<2;i++)gained+=collectCoin(save,state(),{id:s.id+':crystal-reward:'+i});persist();const node=s.trial?.nodes?.[1];rewardCoins(gained,node&&world?.screenPoint?.({x:node.x,y:1,z:node.z}));toast('Crystal barrier cleared · coins saved.');},impact:(p,hit)=>{world?.combatEffect?.(p,hit);cue(hit?'impact':'wrong');feelImpact(p,hit);},damaged:r=>feelDamage(r),projectile:p=>cue({air:'castAir',fire:'castFire',nature:'castNature',water:'castWater'}[p.element]),projectileImpact:(p,kind)=>world?.elementalFX?.impact(p,kind),attack:a=>{world?.attackEffect?.(a);if(world?.locomotion)world.locomotion.heading=a.heading;},defeat:r=>{cue('defeat');cue('reward');currentRun().rivals++;quest('rival');let gained=0;for(const id of enemyRewardIds(r))gained+=collectCoin(save,state(),{id});persist();const at=world?.screenPoint?.({x:r.x,y:1,z:r.z});if(at)burst(at.x,at.y,{color:partner().color,count:18,spread:90});buzz(HAPTICS.reward);rewardCoins(gained,at);toast(r.spec.name+(nav.combat.remaining?' yields! '+nav.combat.remaining+' more in this group · ':' yields! Path opened · ')+(save.mode==='challenge'?10:5)+' coins saved.');},coin:coin=>{const value=collectCoin(save,state(),coin);if(value){quest('coins',value);persist();cue('coin');world?.coinEffect?.(coin);rewardCoins(value,world?.screenPoint?.(coin));}},retry:reason=>{cue('hurt');feelHurt();persist();world?.retryEffect?.(reason);const thumb=$('#joystick-thumb');if(thumb)thumb.style.transform='';toast(reason==='boulder'?'A rolling boulder! Watch the amber lane and wait in an alcove.':reason==='thorns'?'Watch the green gap. Your coins and English progress are safe.':reason==='leaf-slam'?'Leaf slam! Sidestep the marked sector, then circle behind.':reason==='spore-ring'?'Spore ring! Jump as the ring approaches. Coins and English progress are safe.':reason==='charge'?'Caught by the charge! Try a sidestep or jump. Coins and English progress are safe.':reason==='poison'?'Poison spores! Back to your safe spot.':'Missed the landing. Aim for a flat stone top; jump near its edge. Your coins and English work are safe.');},checkpoint:(text,section)=>{if(section?.trial)quest('trial');persist();},notice:text=>toast(text)});}
function syncWorld(){world.partner=partner().id;world.elementColor=partner().color;const e=state();nav.state=e;configureTravel();nav.setLevel(journey().level);nav.restore(e.position);nav.heading=e.heading;world.viewRig.yaw=e.heading;world.viewRig.inputYaw=null;world.setArea(save.area);world.trailColor=save.wallet?.equipped==='air'?partner().color:TRAILS.find(t=>t.id===save.wallet?.equipped)?.color||partner().color;world.setCosmetics?.({hat:save.wallet?.hat,coat:save.wallet?.coat,camp:save.wallet?.camp});if(world.locomotion)world.locomotion.heading=e.heading;}
async function home(){if(!world)return;pendingCompletion=null;screen='home';task=null;resultCard=false;locked=false;world.paused=false;document.body.classList.remove('playing','cinematic','in-task','guardian-choice');$('#task-layer').innerHTML='';$('#world-labels').innerHTML='';world.setView(true);renderHome();}
function applyLook(){world?.setCosmetics?.({hat:save.wallet?.hat,coat:save.wallet?.coat,camp:save.wallet?.camp});}
function homeFraming(kind){if(!world)return;applyLook();const phone=typeof innerWidth==='number'&&innerWidth<760;world.homeZoom=kind==='onboard'?(phone?1.3:1.15):phone?.8:.8;world.homeLift=phone?(kind==='onboard'?.36:.44):0;}
function renderHome(){if(onboarding){renderOnboarding();return;}homeFraming('camp');document.body.classList.remove('onboarding');const j=journey(),u=unit(),e=state(),words=wordex(j,u),pending=chestPending(e),chapter=pending?runChapter(e):Math.min(4,Math.floor(e.index/4));$('#ui').innerHTML=campMarkup({portrait:partnerPortrait(partner().id,j.level),level:j.level,element:partner().element,nickname:save.nickname,unitTitle:u.title,grade:u.grade,growth:growthState(),guardian:guardianReady(j)?AREAS[unlocked(j)].guardian:null,streak:streakInfo(save),daily:dailyState(save),completed:j.completed,resume:!!(e.index||e.active||e.checkpoint||j.level),runNumber:(j.runCount||0)+1,runLabel:e.active?`${activity(e.active.type)?.object} is waiting`:pending?'A reward chest is waiting':`${CHAPTERS[chapter][0]} · ${AREAS[save.area].name}`,words:{found:words.filter(w=>w.box>0).length,total:words.length},coins:coinText(),due:dueCount(j),partners:PARTNERS.map(p=>({...p,portrait:partnerPortrait(p.id,j.level),selected:p.id===partner().id})),areas:AREAS.map((a,i)=>({...a,selected:i===save.area,locked:i>unlocked(j)})),mode:save.mode,previewHref:`partner-preview.html?partner=${partner().id}&level=${Math.min(partner().previewMax,j.level)}`});}
function lessons(grade=unit().grade){const available=units.filter(u=>u.grade===grade);showModal('Choose your lesson',`<p>Every unit keeps its own creature level, task progress and exact trail checkpoint.</p><div class="grade-tabs">${[5,6,7,8].map(g=>`<button data-do="grade" data-grade="${g}" class="${g===grade?'selected':''}">Grade ${g}<small>${{5:'A1',6:'A1+',7:'A2',8:'A2+'}[g]}</small></button>`).join('')}</div><div class="unit-list">${available.map((u,i)=>{const j=save.journeys[u.id];return`<button class="unit-option ${u.id===save.selected?'selected':''}" data-do="unit" data-unit="${u.id}"><span class="num">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(u.title)}</strong><small>${j?`Level ${j.level} · ${j.completed?'Completed':unlocked(j)+1+' arenas unlocked'}`:'Start a new Level 0 journey'}</small></span></button>`;}).join('')}</div>`);}
function graphicsMenu(){const rows=['explore','task','evolution'].map(phase=>{const m=world.frameMetrics?.snapshot(phase);return `<li>${phase}: ${m?.samples?`${Math.round(m.fps)} fps · p95 ${m.p95.toFixed(1)} ms · ${m.drawCalls} draws · ${Math.round(m.triangles/1000)}k triangles · ${Math.round(m.slow30*100)}% over 33 ms · session worst ${m.sessionWorst.toFixed(1)} ms (${m.samples} recent frames)`:'no play samples yet'}</li>`;}).join('');showModal('Graphics and performance',`<p>Target: 60 fps where practical; stable 30 fps on slower phones. Change settings, play a stretch, then return here to compare observations.</p><div class="graphics-grid">${Object.keys(QUALITY).map(p=>`<button data-do="graphics-preset" data-value="${p}" aria-pressed="${graphics.preset===p}">${p}</button>`).join('')}</div><h3>Resolution cap</h3><div class="graphics-grid">${[.75,1,1.5].map(v=>`<button data-do="graphics-resolution" data-value="${v}" aria-pressed="${graphics.resolution===v}">${v}×</button>`).join('')}</div><button class="secondary wide" data-do="graphics-shadows">Shadows: ${graphics.shadows?'on':'off'}</button><h3>Effects</h3><div class="graphics-grid">${['low','medium','full'].map(v=>`<button data-do="graphics-effects" data-value="${v}" aria-pressed="${graphics.effects===v}">${v}</button>`).join('')}</div><h3>Recent play observations</h3><ul class="frame-observations">${rows}</ul><p>Frame intervals are observed on this browser, with separate exploration, task and evolution samples. These are not GPU timings or a device certification. Menus and hidden-tab gaps are excluded. Test touch, heat and sustained play on real phones.</p><button class="secondary" data-do="graphics-reset">Start a fresh measurement</button><p><a href="partner-preview.html?partner=${partner().id}&level=${journey().level}">Inspect creature animations →</a></p><h3>Device test checklist</h3><p>Play for 15 minutes, include tasks, combat and evolution, then record what you observed. Unchecked items remain untested.</p>${VISUAL_CHECKS.map(([id,label])=>`<label class="device-check">${label}<select data-device-check="${id}"><option value="not-tested">Not tested</option><option value="pass" ${deviceChecks[id]==='pass'?'selected':''}>Pass</option><option value="fail" ${deviceChecks[id]==='fail'?'selected':''}>Needs work</option></select></label>`).join('')}<button class="primary wide" data-do="device-export">Export device report</button>`);}
function saveGraphics(){applyGraphics(world,graphics,typeof devicePixelRatio==='number'?devicePixelRatio:1);world.frameMetrics?.reset();try{localStorage.setItem(GRAPHICS_KEY,JSON.stringify(graphics));}catch{toast('Graphics changed for this session. Device settings could not be saved.');}graphicsMenu();}
function help(){showModal('The Windward Trails',`<p>You are ${esc(save.nickname)}. Each <strong>run</strong> takes about five to eight minutes: four English tasks, one rival group, one trail trial and a reward chest at the end. Five runs make a week and cover all twenty activity types.</p><p><strong>Growing:</strong> your creature grows when you <em>remember</em> words, not when you repeat sets. Missed words come back later in the run. Words you remember on different days earn stars in your Wordex and help your creature reach its next form. Guardians wait at Forms 2, 5 and 10.</p><p><strong>Moving:</strong> on phones use the left joystick, the Jump button and your elemental attack. On a keyboard use W / ↑ forward, S / ↓ back, A and D to turn, Space to jump and J or F to cast. Near a rival your creature faces it: A / D sidestep and W / S approach or retreat. Tap <strong>Follow</strong> to walk to the next discovery.</p><p><strong>Rivals:</strong> Rumblebud charges along an amber line: step aside or jump, then strike while it recovers. Brambleguard slams a marked sector: sidestep and strike its side or back. Mistcap sends purple rings: jump over them and strike while its cap is lowered.</p><p><strong>Trials:</strong> wait in alcoves for boulders, shelter from wind, ride turquoise platforms, follow green gaps between thorns, strike crystal cores when their shells open, and try gold ledges for bonus coins. Falling never costs English progress or coins.</p><p><strong>Every day:</strong> three daily quests pay coins. Rest days never break your trail streak. Coins buy wind trails, hats, coat colours and camp decorations in the Wardrobe.</p><p>Progress saves on this device. Export a backup from the journal to move devices.</p><button class="primary wide" data-do="close-modal">Follow the wind →</button>`);}
function trailShopMarkup(){const w=save.wallet;return shopMarkup({tab:'trail',trails:TRAILS,owned:w.owned,equipped:w.equipped,hat:w.hat,coat:w.coat,camp:w.camp,balance:coinText(),nickname:save.nickname});}
function trailShop(){const w=save.wallet;showModal('Wardrobe',shopMarkup({tab:shopTab,trails:TRAILS,owned:w.owned,equipped:w.equipped,hat:w.hat,coat:w.coat,camp:w.camp,balance:coinText(),nickname:save.nickname}));}
function journal(){const j=journey(),e=state(),chapter=chestPending(e)?runChapter(e):Math.min(4,Math.floor(e.index/4));showModal('Journey journal',`<p>${esc(unit().title)} · Grade ${unit().grade} · Form ${j.level}</p>${growthBar(growthState())}<p>${esc(AREAS[save.area].name)} · Run ${(j.runCount||0)+1} · ${esc(CHAPTERS[chapter][0])}<br><strong>Next:</strong> ${esc(chestPending(e)?'Open the reward chest':activeNode(e)?.object||'Choose a path at the fork')}</p><div class="milestone-summary"><strong>${e.index} / 20 activities this week</strong><small>Each run covers four formats; five runs cover all twenty.${e.checkpoint?` Last saved: ${esc(activity(e.checkpoint.type).object)}.`:''}</small></div><div class="trail-checklist">${ACTIVITIES.map(a=>`<div><span>${a.symbol} ${esc(a.label)}</span><b>${e.completed.some(c=>c.type===a.id)?'✓ this week':'·'}</b></div>`).join('')}</div><p>${dueCount(j)} words are ready for review · ${masteredCount(j)} remembered across several days. Missed words come back later in the run.</p><p>${j.stats.correct} accepted steps · ${j.stats.mistakes} corrections · ${j.stats.hints} hints</p><button class="secondary" data-do="wordex">Wordex →</button><button class="secondary" data-do="trails">Wardrobe · ${coinText()} coins →</button><button class="secondary wide" data-do="graphics">Graphics and performance</button><button class="secondary wide" data-do="music">Music: ${save.music===false?'off':'on'}</button>${typeof navigator!=='undefined'&&typeof navigator.vibrate==='function'?`<button class="secondary wide" data-do="haptics">Vibration: ${save.haptics===false?'off':'on'}</button>`:''}<div class="journal-actions"><button class="secondary" data-do="export">Export backup</button><button class="secondary" data-do="import">Import backup</button>${j.level?'<button class="secondary" data-do="evolution-replay-earned">Replay latest evolution</button>':''}<button class="secondary" data-do="restart">Restart this unit</button></div>`);}
async function enter(){locked=true;syncWorld();await world.loadForm(journey().level);screen='play';locked=false;document.body.classList.add('playing');world.setView(false);world.paused=false;const day=markPlayed(save);persist();if(day.first&&save.tutorial)toast(welcomeLine(day,day.gap));voice.load().catch(()=>{});if(state().battle){showBattle();return;}if(state().active){task=state().active;openTaskView();return;}renderPlay();if(!save.tutorial){save.tutorial=true;persist();toast('Choose a branch. Move with the joystick or WASD; jump with the Jump button or Space. Each discovery teaches its own action.');}}
function renderPlay(){screen='play';task=null;resultCard=false;feedbackText='';correction=null;nearId='';document.body.classList.remove('guardian-choice');const e=state(),j=journey(),pending=chestPending(e),chapter=Math.min(4,Math.floor(e.index/4)),fork=!pending&&!e.choices[chapter]&&e.index<20,done=pending?4:e.index%4,g=growthState();$('#ui').innerHTML=`<button class="play-status" data-do="journal" aria-label="${esc(save.nickname)} Form ${j.level}, run ${(j.runCount||0)+1}, ${done} of 4 tasks. Open journey journal."><img src="${partnerPortrait(partner().id,j.level)}" alt=""><span class="status-text">Form ${j.level}<small>Run ${(j.runCount||0)+1} · ${done}/4</small></span><span class="status-growth" aria-hidden="true"><i style="width:${Math.round(g.progress*100)}%"></i></span><b>◉ <span id="coin-count">${coinText()}</span></b></button><div class="play-dock"><div class="traversal-hint" id="traversal-hint">${fork?'Choose a path with the arrows or joystick.':pending?'Your reward chest waits just ahead!':''}</div><div class="joystick" id="joystick" aria-label="Move your creature"><div id="joystick-thumb"></div></div>${fork?`<div class="fork-actions"><button data-do="branch" data-side="left" aria-label="Left: ${esc(CHAPTERS[chapter][1])}. ${esc(firstOnBranch('left'))}">↖<small>Left</small></button><button data-do="branch" data-side="right" aria-label="Right: ${esc(CHAPTERS[chapter][2])}. ${esc(firstOnBranch('right'))}">↗<small>Right</small></button></div>`:`<button class="attack-button" id="attack-button" style="--cast-color:${elementalAttack(partner().id).color}" data-do="attack" aria-label="${elementalAttack(partner().id).name}: ranged elemental attack">✦<small>${elementalAttack(partner().id).label}</small></button><button class="jump-button" id="jump-button" data-do="jump" aria-label="Jump">↑<small>JUMP</small></button><div class="context-action" id="context-action"><small id="context-name"></small><button id="context-button" data-do="follow" aria-label="Follow trail to the next discovery">›<small>Follow</small></button></div>`}</div>`;$('#task-layer').innerHTML='';joystick();}
function firstOnBranch(side){const e=state(),c=Math.floor(e.index/4),copy={...e,choices:e.choices.slice()};copy.choices[c]=side;return activity(currentType(copy)).object+' first';}
